def tool(data, params):
    code = params['series']
    s = data[code]
    y0 = params.get('y0', 2010)
    y1 = params.get('y1', 2015)
    unit = params.get('unit')
    if unit is None or unit not in s:
        unit = sorted(s.keys())[0]
    ser = s[unit]
    def cagr(a, b, ya, yb):
        if a is None or b is None or a <= 0 or b <= 0 or yb <= ya:
            return None
        return (math.pow(b / a, 1.0 / (yb - ya)) - 1.0) * 100.0
    res = {}
    for c in ser:
        if c not in data['regions']:
            continue
        d = ser[c]
        yrs = [y for y in d if d[y] is not None]
        if y0 not in d or y1 not in d or d[y0] is None or d[y1] is None:
            continue
        late = [y for y in yrs if y > y1]
        if not late:
            continue
        yl = max(late)
        r1 = cagr(d[y0], d[y1], y0, y1)
        r2 = cagr(d[y1], d[yl], y1, yl)
        if r1 is None or r2 is None:
            continue
        res[c] = (r1, r2, yl)
    facts = {}
    facts['countries_computed'] = len(res)
    if not res:
        return {'facts': facts, 'summary': 'No country has data for ' + str(y0) + ', ' + str(y1) + ' and a later year.'}
    m1 = statistics.median([v[0] for v in res.values()])
    m2 = statistics.median([v[1] for v in res.values()])
    facts['median_rate_first_pct'] = round(m1, 3)
    facts['median_rate_second_pct'] = round(m2, 3)
    facts['median_latest_year'] = statistics.median([v[2] for v in res.values()])
    ratios = [v[1] / v[0] for v in res.values() if abs(v[0]) > 1e-9]
    if ratios:
        facts['median_country_ratio'] = round(statistics.median(ratios), 3)
    facts['countries_ratio_at_least_2'] = len([r for r in ratios if r >= 2])
    facts['countries_accelerating'] = len([v for v in res.values() if v[1] > v[0]])
    w = ser.get('WLD')
    wtxt = 'World aggregate absent.'
    if w is not None:
        wy = [y for y in w if w[y] is not None and y > y1]
        if y0 in w and y1 in w and wy:
            yl = max(wy)
            a = cagr(w[y0], w[y1], y0, y1)
            b = cagr(w[y1], w[yl], y1, yl)
            if a is not None and b is not None:
                facts['world_rate_first_pct'] = round(a, 3)
                facts['world_rate_second_pct'] = round(b, 3)
                facts['world_latest_year'] = yl
                if abs(a) > 1e-9:
                    facts['world_ratio'] = round(b / a, 3)
                    wtxt = 'World ratio of rates is ' + str(round(b / a, 2)) + ' against the threshold of 2 (' + str(yl) + ').'
    summary = 'Compound annual change of ' + code + ' in ' + unit + ': median across ' + str(len(res)) + ' countries ' + str(round(m1, 2)) + ' per cent a year for ' + str(y0) + '-' + str(y1) + ' and ' + str(round(m2, 2)) + ' per cent for ' + str(y1) + ' to the latest year. ' + wtxt + ' Countries lacking either endpoint or with non-positive values are excluded; target 7.3 can be read as a doubling of the rate or of the level of improvement.'
    return {'facts': facts, 'summary': summary}

