def tool(data, params):
    legal = params['legal']
    supp = params['supportive']
    enf = params['enforcement']
    ds = {'legal': data[legal], 'supportive': data[supp], 'enforcement': data[enf]}
    regions = data['regions']
    names = data['names']
    def span(d):
        out = {}
        for u, yrs in d.items():
            ys = sorted(y for y, v in yrs.items() if v is not None)
            if ys:
                out[u] = (ys[0], yrs[ys[0]], ys[-1], yrs[ys[-1]])
        return out
    sp = {k: span(v) for k, v in ds.items()}
    units = [u for u in sp['legal'] if u in sp['supportive'] or u in sp['enforcement']]
    facts = {}
    rows = []
    for u in units:
        l = sp['legal'][u]
        row = {'u': u, 'l0': l[1], 'l1': l[3], 'y0': l[0], 'y1': l[2]}
        facts['legal_change_' + u] = round(l[3] - l[1], 2)
        facts['legal_first_year_' + u] = l[0]
        facts['legal_last_year_' + u] = l[2]
        for k in ('supportive', 'enforcement'):
            s = sp[k].get(u)
            if s:
                facts[k + '_change_' + u] = round(s[3] - s[1], 2)
                facts[k + '_latest_' + u] = round(s[3], 2)
                g = l[3] - s[3]
                facts['gap_legal_minus_' + k + '_' + u] = round(g, 2)
                row[k] = g
        rows.append(row)
    gaps = [r['enforcement'] for r in rows if 'enforcement' in r]
    sg = [r['supportive'] for r in rows if 'supportive' in r]
    facts['n_units_legal'] = len(rows)
    facts['n_units_with_enforcement'] = len(gaps)
    facts['n_units_with_supportive'] = len(sg)
    if gaps:
        facts['median_legal_minus_enforcement_gap'] = round(statistics.median(gaps), 2)
        facts['max_legal_minus_enforcement_gap'] = round(max(gaps), 2)
    if sg:
        facts['median_legal_minus_supportive_gap'] = round(statistics.median(sg), 2)
    if rows:
        facts['median_legal_change'] = round(statistics.median([r['l1'] - r['l0'] for r in rows]), 2)
    summary = 'Legal, supportive and enforcement scores were compared for ' + str(len(rows)) + ' units, using each unit\'s earliest and latest available year. Median legal-minus-enforcement gap: ' + (str(facts['median_legal_minus_enforcement_gap']) if gaps else 'not available') + ' index points. Coverage differs by series and year; where a series is missing for a unit no gap is computed.'
    return {'facts': facts, 'summary': summary}

