def tool(data, params):
    code = params['series']
    y0 = int(params['start_year'])
    y1 = int(params['end_year'])
    region = params.get('region')
    minspan = int(params.get('min_span', 3))
    series = data[code]
    regions = data['regions']
    names = data['names']
    slopes = {}
    for c, yrs in series.items():
        if c not in regions:
            continue
        if region and regions[c] != region:
            continue
        pts = [(int(y), v) for y, v in yrs.items() if v is not None and y0 <= int(y) <= y1]
        if len(pts) < 2:
            continue
        pts.sort()
        if pts[-1][0] - pts[0][0] < minspan:
            continue
        slopes[c] = (pts[-1][1] - pts[0][1]) / (pts[-1][0] - pts[0][0])
    facts = {}
    facts['countries_in_fixed_set'] = len(slopes)
    if len(slopes) == 0:
        return {'facts': facts, 'summary': 'No country has two or more observations at least ' + str(minspan) + ' years apart in ' + str(y0) + '-' + str(y1) + '; no trend can be estimated.'}
    vals = list(slopes.values())
    med = statistics.median(vals)
    mean = statistics.mean(vals)
    facts['median_annual_change_pp'] = round(med, 3)
    facts['mean_annual_change_pp'] = round(mean, 3)
    facts['countries_declining'] = len([v for v in vals if v < 0])
    best = min(slopes, key=lambda k: slopes[k])
    worst = max(slopes, key=lambda k: slopes[k])
    facts['fastest_decline_country'] = names.get(best, best)
    facts['fastest_decline_pp_per_year'] = round(slopes[best], 3)
    facts['slowest_country'] = names.get(worst, worst)
    facts['slowest_pp_per_year'] = round(slopes[worst], 3)
    byreg = {}
    for c, s in slopes.items():
        byreg.setdefault(regions[c], []).append(s)
    for r, l in sorted(byreg.items()):
        facts['median_change_' + r] = round(statistics.median(l), 3)
    summary = 'Across ' + str(len(slopes)) + ' countries, each measured only between its own first and last observation within ' + str(y0) + '-' + str(y1) + ', the median annual change in ' + code + ' is ' + str(round(med, 3)) + ' percentage points per year (mean ' + str(round(mean, 3)) + '). ' + str(facts['countries_declining']) + ' countries show a decline. Survey rounds differ by country, so observation years are not aligned; countries with fewer than two rounds or spans under ' + str(minspan) + ' years are excluded.'
    return {'facts': facts, 'summary': summary}

