def tool(data, params):
    legal = params['legal']
    supp = params['supportive']
    enf = params['enforcement']
    unit = params.get('unit', 'all')
    names = data['names']
    def get(code):
        d = data[code]
        if unit in d:
            return d[unit]
        for u in d:
            return d[u]
        return {}
    L = get(legal)
    S = get(supp)
    E = get(enf)
    def span(s):
        ys = sorted(y for y in s if s[y] is not None)
        if not ys:
            return None
        return (ys[0], s[ys[0]], ys[-1], s[ys[-1]])
    sl = span(L)
    ss = span(S)
    se = span(E)
    facts = {}
    parts = []
    for tag, sp in (('legal', sl), ('supportive', ss), ('enforcement', se)):
        if sp is None:
            facts[tag + '_available'] = 'no data'
            parts.append(tag + ': no data')
            continue
        y0, v0, y1, v1 = sp
        facts[tag + '_first_year'] = y0
        facts[tag + '_first'] = round(v0, 2)
        facts[tag + '_last_year'] = y1
        facts[tag + '_last'] = round(v1, 2)
        facts[tag + '_change'] = round(v1 - v0, 2)
        parts.append(tag + ' ' + str(round(v0, 1)) + ' in ' + str(y0) + ' to ' + str(round(v1, 1)) + ' in ' + str(y1))
    if sl and ss:
        facts['gap_legal_minus_supportive_latest'] = round(sl[3] - ss[3], 2)
    if sl and se:
        facts['gap_legal_minus_enforcement_latest'] = round(sl[3] - se[3], 2)
    facts['countries_with_legal_data'] = len(L)
    summary = 'Scores on a 0-100 scale: ' + '; '.join(parts) + '. Gaps are legal score minus the other index in the latest year; missing years are left blank.'
    return {'facts': facts, 'summary': summary}

