def tool(data, params):
    code = params['series']
    y0 = params.get('start', 2010)
    y1 = params.get('mid', 2015)
    s = data[code]
    unit = list(s.keys())[0] if s else None
    if unit is None:
        return {'facts': {'status': 'no data'}, 'summary': 'No data are available for the series.'}
    byc = s[unit]
    regions = data['regions']
    def rate(a, b, n):
        if a is None or b is None or a <= 0 or b <= 0 or n <= 0:
            return None
        return (math.pow(b / a, 1.0 / n) - 1) * 100
    rates1 = {}
    rates2 = {}
    latest_years = []
    for c in regions:
        d = byc.get(c)
        if not d:
            continue
        yrs = [y for y in d if y > y1 and d[y] is not None]
        if y0 in d and y1 in d and yrs:
            ly = max(yrs)
            r1 = rate(d[y0], d[y1], y1 - y0)
            r2 = rate(d[y1], d[ly], ly - y1)
            if r1 is not None and r2 is not None:
                rates1[c] = r1
                rates2[c] = r2
                latest_years.append(ly)
    facts = {'unit': unit, 'countries_compared': len(rates1)}
    if rates1:
        facts['median_rate_first_period_pct'] = round(statistics.median(list(rates1.values())), 3)
        facts['median_rate_second_period_pct'] = round(statistics.median(list(rates2.values())), 3)
        facts['median_latest_year'] = statistics.median(latest_years)
        m1 = statistics.median(list(rates1.values()))
        m2 = statistics.median(list(rates2.values()))
        if m1 != 0:
            facts['median_ratio_second_to_first'] = round(m2 / m1, 3)
        faster = len([c for c in rates1 if rates1[c] != 0 and rates2[c] / rates1[c] >= 2 and rates1[c] * rates2[c] > 0])
        facts['countries_with_ratio_at_least_2'] = faster
    w = byc.get('WLD')
    if w and y0 in w and y1 in w:
        ly = max([y for y in w if y > y1] or [y1])
        a = rate(w[y0], w[y1], y1 - y0)
        b = rate(w[y1], w[ly], ly - y1)
        if a is not None and b is not None:
            facts['world_rate_first_pct'] = round(a, 3)
            facts['world_rate_second_pct'] = round(b, 3)
            facts['world_latest_year'] = ly
            if a != 0:
                facts['world_ratio'] = round(b / a, 3)
    summary = 'Compound annual change of ' + code + ' (' + str(unit) + ') was computed for ' + str(y0) + '-' + str(y1) + ' and ' + str(y1) + '-latest across ' + str(len(rates1)) + ' countries. Countries lacking either end year are omitted; the reading of the target as a ratio of 2 is one interpretation.'
    return {'facts': facts, 'summary': summary}

