def tool(data, params):
    code = params['series']
    y0 = params.get('year_a', 2015)
    y1 = params.get('year_b', 2020)
    y2 = params.get('year_c', 2025)
    s = data[code]
    regions = data['regions']
    names = data['names']
    facts = {}
    lines = []
    def val(d, y):
        v = d.get(y)
        if v is None:
            v = d.get(str(y))
        return v
    for label, ya in (('15_25', y0), ('20_25', y1)):
        groups = {}
        for unit, yrs in s.items():
            if unit not in regions:
                continue
            a = val(yrs, ya)
            b = val(yrs, y2)
            if a is None or b is None:
                continue
            g = regions[unit]
            groups.setdefault(g, []).append(b - a)
        allv = [x for g in groups for x in groups[g]]
        facts['n_' + label] = len(allv)
        if allv:
            facts['mean_change_' + label] = round(sum(allv) / len(allv), 2)
            facts['rose_' + label] = len([x for x in allv if x > 0])
        for g in sorted(groups):
            v = groups[g]
            nm = names.get(g, g)
            facts[label + '_' + g + '_mean'] = round(sum(v) / len(v), 2)
            facts[label + '_' + g + '_rose'] = len([x for x in v if x > 0])
            facts[label + '_' + g + '_n'] = len(v)
        lines.append('Between ' + str(ya) + ' and ' + str(y2) + ', ' + str(facts.get('rose_' + label, 0)) + ' of ' + str(len(allv)) + ' countries with data in both years recorded a higher score; the mean change was ' + str(facts.get('mean_change_' + label, 'n/a')) + ' points.')
    lines.append('Countries lacking a value in either year are excluded; the index is a 0 to 100 score.')
    return {'facts': facts, 'summary': ' '.join(lines)}

