    names = data['names']
    def pick(series, c):
        d = series.get(c)
        if d is None:
            return None
        v = d.get(year)
        if v is None:
            v = d.get(str(year))
        return v
    ratios = {}
    rn = {}
    rd = {}
    for c in regions:
        a = pick(num, c)
        b = pick(den, c)
        if a is None or b is None or b == 0:
            continue
        ratios[c] = a * scale / b
        r = regions[c]
        rn[r] = rn.get(r, 0.0) + a
        rd[r] = rd.get(r, 0.0) + b
    facts = {}
    facts['countries_with_both'] = len(ratios)
    if len(ratios) == 0:
        return {'facts': facts, 'summary': 'No country has both series for ' + str(year) + '; no ratio can be stated.'}
