            parts.append(str(r) + ' ' + str(round(v, 4)))
    summary = ('Ratio of ' + num_code + ' to ' + den_code + ' in ' + str(year) + ' across ' + str(len(ratios)) + ' countries with both series: median ' + str(facts['median_ratio']) + ', highest ' + facts['highest_country'] + ' at ' + str(facts['highest_ratio']) + ', lowest ' + facts['lowest_country'] + ' at ' + str(facts['lowest_ratio']) + '. Regional ratios are sums of numerators over sums of denominators for countries with both values: ' + '; '.join(parts) + '. Countries lacking either series are omitted.')
