def tool(data, params):
    legal = params['legal']
    supp = params['supportive']
    enf = params['enforcement']
    unit = params.get('unit', 'all')
    names = data['names']
    def pick(code):
        d = data[code]
        out = {}
        for u in d:
            for y in d[u]:
                v = d[u][y]
                if v is not None:
                    out[int(y)] = v
        return out
    def ends(code, unit_code):
        d = data[code].get(unit_code, {})
        pts = {}
        for y in d:
            if d[y] is not None:
                pts[int(y)] = d[y]
        return pts
    units = set()
    for c in (legal, supp, enf):
        for u in data[c]:
            units.add(u)
    units = sorted(units)
    facts = {}
    rows = []
    for u in units:
        L = ends(legal, u)
        S = ends(supp, u)
        E = ends(enf, u)
        if not L:
            continue
        y0 = min(L)
        y1 = max(L)
        nm = names.get(u, u)
        row = {'u': u, 'n': nm, 'y0': y0, 'y1': y1, 'l0': L[y0], 'l1': L[y1]}
        row['dl'] = round(L[y1] - L[y0], 2)
        for tag, X in (('s', S), ('e', E)):
            if X:
                a = min(X)
                b = max(X)
                row[tag + '1'] = X[b]
                row[tag + 'y1'] = b
                row[tag + 'd'] = round(X[b] - X[a], 2)
                if b in L:
                    row[tag + 'gap'] = round(L[b] - X[b], 2)
        rows.append(row)
    for r in rows:
        k = r['u']
        facts[k + '_legal_first'] = r['l0']
        facts[k + '_legal_first_year'] = r['y0']
        facts[k + '_legal_latest'] = r['l1']
        facts[k + '_legal_latest_year'] = r['y1']
        facts[k + '_legal_change'] = r['dl']
        for tag, lab in (('s', 'supportive'), ('e', 'enforcement')):
            if tag + '1' in r:
                facts[k + '_' + lab + '_latest'] = r[tag + '1']
                facts[k + '_' + lab + '_change'] = r[tag + 'd']
            if tag + 'gap' in r:
                facts[k + '_legal_minus_' + lab] = r[tag + 'gap']
    facts['units_covered'] = len(rows)
    with_gap = [r for r in rows if 'egap' in r]
    if with_gap:
