        facts['widest_enforcement_gap_unit'] = w['n']
        facts['widest_enforcement_gap'] = w['egap']
    summary = 'Legal Framework Index, Supportive Framework Index and Enforcement Perceptions Index were compared for ' + str(len(rows)) + ' units; gaps are the legal score minus the other score in the latest shared year. Units lacking a series are omitted from its gap figures.'
