                elif str(year) in s and s[str(year)] is not None:
                    res[c] = s[str(year)]
        return res

    def quart(v, q):
        s = sorted(v)
        n = len(s)
        if n == 0:
            return None
        p = (n - 1) * q
        lo = int(math.floor(p))
        hi = int(math.ceil(p))
        return s[lo] + (s[hi] - s[lo]) * (p - lo)

    sample = {}
