def tool(data, params):
    prev_code = params['prevalence_series']
    pop_code = params['population_series']
    base = int(params['baseline_year'])
    years = [int(y) for y in params['target_years']]
    share = float(params['reduction_share'])
    prev = data[prev_code]
    pop = data[pop_code]
    regions = data['regions']
    names = data['names']
    def nearest(d, y, window):
        best = None
        for k in d:
            ky = int(k)
            if abs(ky - y) <= window and d[k] is not None:
                if best is None or abs(ky - y) < abs(best - y):
                    best = ky
        return best
    def counts(y):
        out = {}
        for c in regions:
            if c not in prev or c not in pop:
                continue
            yp = nearest(prev[c], y, 2)
            if yp is None:
                continue
            yq = nearest(pop[c], yp, 0)
            if yq is None:
                continue
            out[c] = prev[c][yp] / 100.0 * pop[c][yq]
        return out
    facts = {}
    b = counts(base)
    btotal = sum(b.values())
    facts['countries_with_baseline'] = len(b)
    facts['baseline_year'] = base
    facts['baseline_affected_total'] = round(btotal)
    reg = {}
    for c in b:
        r = regions[c]
        reg[r] = reg.get(r, 0) + b[c]
    for r in sorted(reg):
        facts['baseline_affected_' + str(r)] = round(reg[r])
    facts['target_affected_ceiling'] = round(btotal * (1 - share))
    for y in years:
        cy = counts(y)
        common = [c for c in cy if c in b]
        facts['countries_with_data_' + str(y)] = len(cy)
        facts['affected_total_' + str(y)] = round(sum(cy.values()))
        bc = sum(b[c] for c in common)
        yc = sum(cy[c] for c in common)
        if bc > 0:
            facts['change_pct_common_' + str(y)] = round((yc - bc) / bc * 100, 1)
    top = sorted(b, key=lambda c: -b[c])[:3]
    facts['largest_baseline_burdens'] = ', '.join([names.get(c, c) for c in top])
    summary = ('Prevalence from ' + prev_code + ' was multiplied by under-five population from ' + pop_code + ' for ' + str(len(b)) + ' countries with a ' + str(base) + ' value (nearest survey within two years). Baseline affected children: ' + str(round(btotal)) + '. A ' + str(round(share * 100)) + ' per cent reduction implies a ceiling of ' + str(round(btotal * (1 - share))) + '. Countries without survey data are omitted, so totals are partial sums, not global estimates.')
    return {'facts': facts, 'summary': summary}

