def tool(data, params):
    code = params['series']
    target = params['target']
    base_year = params.get('base_year', 2015)
    units = data[code]
    names = data['names']
    regions = data['regions']
    rows = []
    for u in sorted(units.keys()):
        if u in regions or u in names:
            pass
        ser = units[u]
        ys = sorted([y for y in ser.keys() if ser[y] is not None])
        if not ys:
            continue
        last = ys[-1]
        v = ser[last]
        bys = [y for y in ys if y <= base_year]
        if not bys or v <= 0:
            continue
        by = bys[-1]
        b = ser[by]
        if b <= 0 or last <= by:
            continue
        ach = (v / b) ** (1.0 / (last - by)) - 1
        r = {'unit': u, 'last': last, 'v': v, 'ach': ach}
        for ty in (2025, 2030):
            n = ty - last
            if n > 0 and target > 0:
                r['need' + str(ty)] = (target / v) ** (1.0 / n) - 1
            else:
                r['need' + str(ty)] = None
        rows.append(r)
    facts = {'series': code, 'target': target, 'units_computed': len(rows)}
    if not rows:
        return {'facts': facts, 'summary': 'No unit holds a positive value in the latest year and a base-year value to compare, so no pace can be computed.'}
    def med(k):
        xs = [r[k] for r in rows if r[k] is not None]
        return round(statistics.median(xs) * 100, 3) if xs else 'n/a'
    facts['median_achieved_pct_per_year'] = med('ach')
    facts['median_needed_2025_pct_per_year'] = med('need2025')
    facts['median_needed_2030_pct_per_year'] = med('need2030')
    on30 = len([r for r in rows if r['need2030'] is not None and r['ach'] <= r['need2030']])
    on25 = len([r for r in rows if r['need2025'] is not None and r['ach'] <= r['need2025']])
    facts['units_on_pace_2025'] = on25
    facts['units_on_pace_2030'] = on30
    facts['median_latest_year'] = statistics.median([r['last'] for r in rows])
    s = 'Across ' + str(len(rows)) + ' units, the median annual change achieved from ' + str(base_year) + ' (or the nearest earlier year) to the latest year is ' + str(facts['median_achieved_pct_per_year']) + ' per cent. Reaching ' + str(target) + ' by 2025 needs a median ' + str(facts['median_needed_2025_pct_per_year']) + ' per cent a year; by 2030, ' + str(facts['median_needed_2030_pct_per_year']) + ' per cent. Units on pace (decline at least as fast as needed): ' + str(on25) + ' for 2025 and ' + str(on30) + ' for 2030. Units whose latest year is 2025 or later have no 2025 rate, and the two target years give two readings of the target.'
    return {'facts': facts, 'summary': s}

