def tool(data, params):
    ra = data[params['rural_access']]
    rp = data[params['rural_pop']]
    ua = data[params['urban_access']]
    up = data[params['urban_pop']]
    base = int(params['base_year'])
    regions = data['regions']
    names = data['names']
    def val(s, c, y):
        d = s.get(c)
        if d is None:
            return None
        v = d.get(y)
        if v is None:
            v = d.get(str(y))
        return v
    def calc(y):
        out = {}
        for c in regions:
            a = val(ra, c, y)
            b = val(rp, c, y)
            e = val(ua, c, y)
            f = val(up, c, y)
            if a is None or b is None or e is None or f is None:
                continue
            out[c] = (100.0 - a) / 100.0 * b + (100.0 - e) / 100.0 * f
        return out
    years = set()
    for c in ra:
        for k in ra[c]:
            years.add(int(k))
    base_res = calc(base)
    latest = base
    latest_res = base_res
    for y in sorted(years, reverse=True):
        if y <= base:
            break
        r = calc(y)
        if len(base_res) > 0 and len(r) >= 0.8 * len(base_res):
            latest = y
            latest_res = r
            break
    facts = {}
    lines = []
