def tool(data, params):
    code = params['series']
    target = params['target']
    base = params.get('base_year', 2015)
    units = data[code]
    names = data['names']
    rows = []
    for unit in units:
        s = units[unit]
        yrs = sorted([y for y in s if s[y] is not None])
        if len(yrs) < 2:
            continue
        last = yrs[-1]
        early = [y for y in yrs if y >= base]
        if len(early) < 2:
            continue
        first = early[0]
        v0 = s[first]
        v1 = s[last]
        if v0 <= 0 or v1 <= 0 or target <= 0 or last == first:
            continue
        achieved = (v1 / v0) ** (1.0 / (last - first)) - 1
        row = {'unit': unit, 'first': first, 'last': last, 'v1': v1, 'achieved': achieved}
        for end in (2025, 2030):
            n = end - last
            if n > 0:
                row['need' + str(end)] = (target / v1) ** (1.0 / n) - 1
            else:
                row['need' + str(end)] = None
        rows.append(row)
    if not rows:
        return {'facts': {'units_used': 0}, 'summary': 'No unit holds two usable positive observations from ' + str(base) + ' onwards, so no pace can be computed.'}
    r = rows[0]
    facts = {'units_used': len(rows), 'unit': r['unit'], 'base_observation_year': r['first'], 'latest_year': r['last'], 'latest_value': round(r['v1'], 4), 'target': target, 'achieved_annual_rate_pct': round(r['achieved'] * 100, 3)}
    parts = []
    for end in (2025, 2030):
        k = 'need' + str(end)
        if r[k] is None:
            facts['needed_annual_rate_pct_' + str(end)] = 'latest year at or after ' + str(end)
        else:
            facts['needed_annual_rate_pct_' + str(end)] = round(r[k] * 100, 3)
            facts['on_track_' + str(end)] = 'yes' if r['achieved'] <= r[k] else 'no'
            parts.append('by ' + str(end) + ' the required rate is ' + str(round(r[k] * 100, 3)) + ' per cent a year')
    summary = 'For ' + code + ' (' + r['unit'] + '), the latest value is ' + str(round(r['v1'], 4)) + ' in ' + str(r['last']) + ' against a target of ' + str(target) + '. The rate achieved from ' + str(r['first']) + ' is ' + str(round(r['achieved'] * 100, 3)) + ' per cent a year; ' + '; '.join(parts) + '. Negative rates denote decline. The target year of 2025 or 2030 is a reading of the target text that the data cannot settle, and years without observations are not interpolated.'
    return {'facts': facts, 'summary': summary}

