def tool(data, params):
    law = params['law']
    sfr = params['sfr']
    enf = params['enf']
    unit = params.get('unit')
    y0 = params.get('start', 2015)
    y1 = params.get('mid', 2020)
    y2 = params.get('end', 2025)
    regions = data['regions']
    facts = {}
    def ser(code):
        d = data[code]
        if unit is not None and unit in d:
            return d[unit]
        for u in d:
            return d[u]
        return {}
    def vals(s, y):
        return {c: s[y] for c in regions if y in s and s[y] is not None} if False else {c: v for c, v in s.get(y, {}).items() if c in regions and v is not None} if False else None
    def at(code, y):
        d = ser(code)
        out = {}
        for c in regions:
            if c in d and y in d[c] and d[c][y] is not None:
                out[c] = d[c][y]
        return out
    def mean(l):
        return round(sum(l) / len(l), 2) if l else None
    def quart(l):
        if len(l) < 2:
            return None
        q = statistics.quantiles(l, n=4, method='inclusive')
        return round(q[2] - q[0], 2)
    names = {'law': law, 'sfr': sfr, 'enf': enf}
    for k in names:
        code = names[k]
        for y in [y0, y1, y2]:
            v = at(code, y)
            l = list(v.values())
            facts[k + '_n_' + str(y)] = len(l)
            facts[k + '_mean_' + str(y)] = mean(l)
            if l:
                facts[k + '_min_' + str(y)] = min(l)
                facts[k + '_max_' + str(y)] = max(l)
                facts[k + '_iqr_' + str(y)] = quart(l)
            reg = {}
            for c in v:
                reg.setdefault(regions[c], []).append(v[c])
            for r in sorted(reg):
                facts[k + '_mean_' + r + '_' + str(y)] = mean(reg[r])
    a = at(law, y0)
    b = at(law, y1)
    e = at(law, y2)
    def count(p, q, tag):
        up = dn = same = 0
        for c in p:
            if c in q:
                if q[c] > p[c]:
                    up += 1
                elif q[c] < p[c]:
                    dn += 1
                else:
                    same += 1
        facts['law_rose_' + tag] = up
        facts['law_fell_' + tag] = dn
        facts['law_same_' + tag] = same
    count(a, e, str(y0) + '_' + str(y2))
    count(b, e, str(y1) + '_' + str(y2))
    L = at(law, y2)
    for k in ['sfr', 'enf']:
        C = at(names[k], y2)
        g = {}
        for c in L:
            if c in C:
                g.setdefault(regions[c], []).append(L[c] - C[c])
        for r in sorted(g):
            facts['gap_law_minus_' + k + '_' + r + '_' + str(y2)] = mean(g[r])
    summary = 'Legal score ' + law + ': mean ' + str(facts.get('law_mean_' + str(y0))) + ' in ' + str(y0) + ', ' + str(facts.get('law_mean_' + str(y1))) + ' in ' + str(y1) + ' and ' + str(facts.get('law_mean_' + str(y2))) + ' in ' + str(y2) + '; ' + str(facts['law_rose_' + str(y0) + '_' + str(y2)]) + ' economies rose, ' + str(facts['law_fell_' + str(y0) + '_' + str(y2)]) + ' fell and ' + str(facts['law_same_' + str(y0) + '_' + str(y2)]) + ' were unchanged over ' + str(y0) + '-' + str(y2) + '. Missing years reduce coverage; see counts.'
    return {'facts': facts, 'summary': summary}

t-ratio-of-two-series-by-country-and-yea.code:
def tool(data, params):
    num_code = params['num']
    den_code = params['den']
    year = params['year']
    scale = params.get('scale', 1.0)
    num = data[num_code]
    den = data[den_code]
    regions = data['regions']
    names = data['names']
    ratios = {}
    for c in regions:
        if c in num and c in den:
            n = num[c].get(year)
            d = den[c].get(year)
            if n is not None and d is not None and d > 0:
                ratios[c] = n * scale / d
    sums = {}
    for c in ratios:
        r = regions[c]
        s = sums.setdefault(r, [0.0, 0.0])
        s[0] += num[c][year] * scale
        s[1] += den[c][year]
    facts = {}
    facts['countries_with_data'] = len(ratios)
    facts['countries_total'] = len(regions)
    if ratios:
        vals = sorted(ratios.values())
        facts['median_ratio'] = round(statistics.median(vals), 4)
        facts['min_ratio'] = round(vals[0], 4)
        facts['max_ratio'] = round(vals[-1], 4)
        hi = max(ratios, key=lambda k: ratios[k])
        lo = min(ratios, key=lambda k: ratios[k])
        facts['highest_country'] = names.get(hi, hi)
        facts['lowest_country'] = names.get(lo, lo)
    for r in sorted(sums):
        if sums[r][1] > 0:
            facts['region_' + r] = round(sums[r][0] / sums[r][1], 4)
    summary = 'In ' + str(year) + ', ' + str(len(ratios)) + ' of ' + str(len(regions)) + ' countries report both series; the ratio is ' + num_code + ' times ' + str(scale) + ' divided by ' + den_code + '. Regional values are pooled sums, not means of country ratios. Countries missing either series are excluded.'
    return {'facts': facts, 'summary': summary}

