        out = {}
        for c in regions:
            ok = True
            for s in (ra, rp, ua, up):
                if c not in s or y not in s[c]:
                    ok = False
            if ok:
                out[c] = (100 - ra[c][y]) / 100 * rp[c][y] + (100 - ua[c][y]) / 100 * up[c][y]
        return out
    base = calc(by)
    years = set()
    for c in ra:
        for k in ra[c]:
            years.add(k)
    latest = by
    for y in sorted(years, reverse=True):
        if len(calc(y)) >= 0.5 * max(len(base), 1):
            latest = y
            break
    facts = {'base_year': by, 'latest_year': latest}
    parts = []
    for y in (by, latest):
        res = base if y == by else calc(y)
        total = sum(res.values())
