def tool(data, params):
    law = params['law']
    sfr = params['sfr']
    enf = params['enf']
    y0 = params['start_year']
    y1 = params['mid_year']
    y2 = params['end_year']
    regions = data['regions']
    codes = [law, sfr, enf]
    def get(code, year):
        out = {}
        for unit in data[code]:
            for yr, v in data[code][unit].items():
                if int(yr) == year and v is not None and unit in regions:
                    out[unit] = v
        return out
    def mean(xs):
        return round(sum(xs) / len(xs), 2) if xs else None
    def quart(xs):
        if len(xs) < 4:
            return None
        q = statistics.quantiles(xs, n=4)
        return round(q[2] - q[0], 2)
    facts = {}
    for c in codes:
        for y in [y0, y1, y2]:
            d = get(c, y)
            vals = list(d.values())
            k = c + '_' + str(y)
            facts[k + '_n'] = len(vals)
            facts[k + '_mean'] = mean(vals)
            if vals:
                facts[k + '_min'] = round(min(vals), 2)
                facts[k + '_max'] = round(max(vals), 2)
            facts[k + '_iqr'] = quart(vals)
            groups = {}
            for u, v in d.items():
                groups.setdefault(regions[u], []).append(v)
            for g in sorted(groups):
                facts[k + '_mean_' + g] = mean(groups[g])
    a = get(law, y0)
    b = get(law, y1)
    e = get(law, y2)
    def cnt(p, q, tag):
        r = f = s = 0
        for u in q:
            if u in p:
                if q[u] > p[u]:
                    r += 1
                elif q[u] < p[u]:
                    f += 1
                else:
                    s += 1
        facts['law_' + tag + '_rose'] = r
        facts['law_' + tag + '_fell'] = f
        facts['law_' + tag + '_same'] = s
    cnt(a, e, str(y0) + '_' + str(y2))
    cnt(b, e, str(y1) + '_' + str(y2))
    L = get(law, y2)
    for c in [sfr, enf]:
        o = get(c, y2)
        groups = {}
        for u in L:
            if u in o:
                groups.setdefault(regions[u], []).append(L[u] - o[u])
        for g in sorted(groups):
            facts['gap_law_minus_' + c + '_' + str(y2) + '_' + g] = mean(groups[g])
        allg = [x for v in groups.values() for x in v]
        facts['gap_law_minus_' + c + '_' + str(y2) + '_all'] = mean(allg)
    summary = 'Legal score ' + law + ' averaged ' + str(facts.get(law + '_' + str(y2) + '_mean')) + ' across ' + str(facts.get(law + '_' + str(y2) + '_n')) + ' economies in ' + str(y2) + '; ' + str(facts['law_' + str(y0) + '_' + str(y2) + '_rose']) + ' rose over ' + str(y0) + '-' + str(y2) + '. Groups are the regional codes supplied; missing years are omitted.'
    return {'facts': facts, 'summary': summary}

