def tool(data, params):
    rural_acc = data[params['rural_access']]
    rural_pop = data[params['rural_pop']]
    urban_acc = data[params['urban_access']]
    urban_pop = data[params['urban_pop']]
    regions = data['regions']
    names = data['names']
    base = int(params.get('base_year', 2015))
    def val(series, c, y):
        d = series.get(c)
        if not d:
            return None
        return d.get(y)
    def pick(series, c):
        d = series.get(c)
        if not d:
            return None
        return d
    def lacking(c, y):
        total = 0.0
        ok = False
        for acc, pop in ((rural_acc, rural_pop), (urban_acc, urban_pop)):
            a = val(acc, c, y)
            p = val(pop, c, y)
            if a is None or p is None:
                return None
            total += (100.0 - a) / 100.0 * p
        return total
    def years_available():
        ys = set()
        for c in regions:
            for series in (rural_acc, urban_acc):
                d = series.get(c)
                if d:
                    for y in d:
                        ys.add(y)
        return ys
    ys = years_available()
    ysi = sorted(ys, key=lambda y: int(y))
    # latest year where at least 20 countries have a full computation
    latest = None
    for y in reversed(ysi):
        n = 0
        for c in regions:
            if lacking(c, y) is not None:
                n += 1
        if n >= 20:
            latest = y
            break
    facts = {}
    parts = []
    def block(y, tag):
        by_c = {}
        for c in regions:
            v = lacking(c, y)
            if v is not None:
                by_c[c] = v
        by_r = {}
        for c, v in by_c.items():
            r = regions[c]
            by_r[r] = by_r.get(r, 0.0) + v
        tot = sum(by_r.values())
        facts[tag + '_countries_covered'] = len(by_c)
        facts[tag + '_world_total_people'] = round(tot)
        for r in sorted(by_r):
            facts[tag + '_region_' + str(r) + '_people'] = round(by_r[r])
            if tot > 0:
                facts[tag + '_region_' + str(r) + '_share_pct'] = round(100.0 * by_r[r] / tot, 2)
        top = sorted(by_c.items(), key=lambda kv: -kv[1])[:5]
        facts[tag + '_top_countries'] = ', '.join(names.get(c, c) + ' ' + str(round(v)) for c, v in top)
        return tot, len(by_c)
    by = str(base)
    key_base = None
    for y in ysi:
        if int(y) == base:
            key_base = y
    if key_base is None:
        key_base = by
    t1, n1 = block(key_base, 'y' + by)
    parts.append('In ' + by + ' ' + str(round(t1)) + ' people lacked electricity across ' + str(n1) + ' countries with complete rural and urban data.')
    if latest is not None:
        t2, n2 = block(latest, 'latest')
        facts['latest_year'] = int(latest)
        parts.append('In ' + str(latest) + ' the figure was ' + str(round(t2)) + ' people across ' + str(n2) + ' countries.')
    else:
        parts.append('No later year has sufficient coverage.')
    parts.append('Countries missing any of the four inputs are excluded, so totals understate the full count.')
    return {'facts': facts, 'summary': ' '.join(parts)}

