def tool(data, params):
    rural_acc = data[params['rural_access']]
    urban_acc = data[params['urban_access']]
    rural_pop = data[params['rural_pop']]
    urban_pop = data[params['urban_pop']]
    base = params.get('base_year', 2015)
    regions = data['regions']
    names = data['names']

    def val(series, c, y):
        d = series.get(c)
        if d is None:
            return None
        return d.get(y)

    def lacking(c, y):
        ra = val(rural_acc, c, y)
        ua = val(urban_acc, c, y)
        rp = val(rural_pop, c, y)
        up = val(urban_pop, c, y)
        if ra is None or ua is None or rp is None or up is None:
            return None
        return (100.0 - ra) / 100.0 * rp + (100.0 - ua) / 100.0 * up

    def latest_year():
        ys = set()
        for c in regions:
            for y in rural_acc.get(c, {}):
                if y > base and lacking(c, y) is not None:
                    ys.add(y)
        if not ys:
            return None
        return max(ys)

    ly = latest_year()
    facts = {}
    parts = []
    for label, y in [('base', base), ('latest', ly)]:
        if y is None:
            facts[label + '_year'] = 'none'
            continue
        tot = {}
        ctry = {}
        for c in regions:
            v = lacking(c, y)
            if v is None:
                continue
            ctry[c] = v
            r = regions[c]
            tot[r] = tot.get(r, 0.0) + v
        world = sum(tot.values())
        facts[label + '_year'] = y
        facts[label + '_countries'] = len(ctry)
        facts[label + '_total_people'] = round(world)
        for r in sorted(tot):
            facts[label + '_' + str(r) + '_people'] = round(tot[r])
            if world > 0:
                facts[label + '_' + str(r) + '_share_pct'] = round(100.0 * tot[r] / world, 2)
        if ctry:
            top = sorted(ctry, key=lambda k: -ctry[k])[:3]
            facts[label + '_top3'] = ', '.join(names.get(k, k) + ' ' + str(round(ctry[k])) for k in top)
        parts.append('In ' + str(y) + ', ' + str(round(world)) + ' people lacked electricity access across ' + str(len(ctry)) + ' countries with complete data.')
    summary = ' '.join(parts) + ' Countries missing any of the four inputs in a year are excluded, so totals understate the global figure.'
    return {'facts': facts, 'summary': summary}

