t-wbl-change-and-gap~birchwood/analyst-1.code:
def tool(data, params):
    law = params['law']
    sfr = params['sfr']
    enf = params['enf']
    y0 = int(params['start'])
    y1 = int(params['mid'])
    y2 = int(params['end'])
    codes = [law, sfr, enf]
    regions = data['regions']
    def vals(code, year):
        d = data[code]
        out = {}
        for u in d:
            for y in d[u]:
                if int(y) == year and d[u][y] is not None and u in regions:
                    out[u] = d[u][y]
        return out
    def getv(code, year):
        out = {}
        for unit in data[code]:
            if unit in regions:
                s = data[code][unit]
                for k in s:
                    if int(k) == year and s[k] is not None:
                        out[unit] = s[k]
        return out
    def mean(l):
        return sum(l) / len(l) if l else None
    def quart(l):
        if len(l) < 4:
            return None
        q = statistics.quantiles(l, n=4)
        return q[2] - q[0]
    facts = {}
    for c in codes:
        for y in [y0, y1, y2]:
            v = list(getv(c, y).values())
            k = c + '_' + str(y)
            facts[k + '_n'] = len(v)
            if v:
                facts[k + '_mean'] = round(mean(v), 2)
                facts[k + '_min'] = min(v)
                facts[k + '_max'] = max(v)
                iq = quart(v)
                if iq is not None:
                    facts[k + '_iqr'] = round(iq, 2)
    def change(a, b):
        A = getv(law, a)
        B = getv(law, b)
        up = dn = same = 0
        for u in A:
            if u in B:
                if B[u] > A[u]:
                    up += 1
                elif B[u] < A[u]:
                    dn += 1
                else:
                    same += 1
        return up, dn, same
    for a, b in [(y0, y2), (y1, y2)]:
        r = change(a, b)
        t = str(a) + '_' + str(b)
        facts['rose_' + t] = r[0]
        facts['fell_' + t] = r[1]
        facts['same_' + t] = r[2]
    L = getv(law, y2)
    for c in [sfr, enf]:
        C = getv(c, y2)
        gaps = {}
        for u in L:
            if u in C:
                g = regions[u]
                gaps.setdefault(g, []).append(L[u] - C[u])
        for g in sorted(gaps):
            facts['gap_' + c + '_' + g] = round(mean(gaps[g]), 2)
    for g in sorted(set(regions.values())):
        for y in [y0, y1, y2]:
            v = [x for u, x in getv(law, y).items() if regions[u] == g]
            if v:
                facts['lawmean_' + g + '_' + str(y)] = round(mean(v), 2)
    summary = 'Legal score changes ' + str(y0) + '-' + str(y2) + ': ' + str(facts['rose_' + str(y0) + '_' + str(y2)]) + ' rose, ' + str(facts['fell_' + str(y0) + '_' + str(y2)]) + ' fell. Group means computed over economies with data.'
    return {'facts': facts, 'summary': summary}

