def tool(data, params):
    rur_a = data[params['rural_access']]
    urb_a = data[params['urban_access']]
    rur_p = data[params['rural_pop']]
    urb_p = data[params['urban_pop']]
    regions = data['regions']
    names = data['names']
    y0 = int(params['base_year'])
    def val(s, c, y):
        return s.get(c, {}).get(y)
    def latest_year():
        best = None
        for c in regions:
            ys = set(rur_a.get(c, {}).keys()) & set(urb_a.get(c, {}).keys()) & set(rur_p.get(c, {}).keys()) & set(urb_p.get(c, {}).keys())
            for y in ys:
                if best is None or y > best:
                    best = y
        return best
    def calc(y):
        out = {}
        for c in regions:
            ra = val(rur_a, c, y)
            ua = val(urb_a, c, y)
            rp = val(rur_p, c, y)
            up = val(urb_p, c, y)
            if ra is None or ua is None or rp is None or up is None:
                continue
            out[c] = (100.0 - ra) / 100.0 * rp + (100.0 - ua) / 100.0 * up
        return out
    ly = latest_year()
    facts = {}
    parts = []
    for label, y in [('base', y0), ('latest', ly)]:
        if y is None:
            facts[label + '_year'] = 'no data'
            continue
        res = calc(y)
        tot = sum(res.values())
        reg = {}
        for c, v in res.items():
            r = regions[c]
            reg[r] = reg.get(r, 0.0) + v
        facts[label + '_year'] = y
        facts[label + '_countries'] = len(res)
        facts[label + '_total_without_access'] = round(tot)
        for r in sorted(reg):
            facts[label + '_' + str(r) + '_total'] = round(reg[r])
            facts[label + '_' + str(r) + '_share_pct'] = round(100.0 * reg[r] / tot, 1) if tot > 0 else 0
        if res:
            top = max(res, key=lambda k: res[k])
            facts[label + '_largest_country'] = names.get(top, top)
            facts[label + '_largest_country_people'] = round(res[top])
        parts.append('In %d, %d people lacked electricity access across %d countries with complete data.' % (y, round(tot), len(res)))
    summary = ' '.join(parts) + ' Totals sum only countries reporting all four series for the year; missing countries are omitted, so totals understate the global figure.'
    return {'facts': facts, 'summary': summary}

