def tool(data, params):
    rate_code = params['rate_series']
    pop_code = params['pop_series']
    year = str(params['year'])
    per = params.get('per', 100000)
    rate = data[rate_code]
    pop = data[pop_code]
    regions = data['regions']
    names = data['names']
    deaths = {}
    missing = 0
    for c in regions:
        r = rate.get(c)
        p = pop.get(c)
        rv = None
        pv = None
        if r is not None:
            rv = r.get(year)
            if rv is None:
                rv = r.get(int(year)) if year.isdigit() else None
        if p is not None:
            pv = p.get(year)
            if pv is None:
                pv = p.get(int(year)) if year.isdigit() else None
        if rv is None or pv is None:
            missing += 1
            continue
        deaths[c] = rv * pv / per
    totals = {}
    for c in deaths:
        g = regions[c]
        totals[g] = totals.get(g, 0) + deaths[c]
    total = sum(deaths.values())
    facts = {'countries_computed': len(deaths), 'countries_missing': missing, 'total_deaths': round(total)}
    if deaths:
        top = sorted(deaths, key=lambda k: -deaths[k])[:3]
        for i, c in enumerate(top):
            facts['top' + str(i + 1) + '_country'] = names.get(c, c)
            facts['top' + str(i + 1) + '_deaths'] = round(deaths[c])
    for g in sorted(totals):
        facts['region_' + g] = round(totals[g])
    summary = 'Estimated deaths in ' + year + ' are the rate multiplied by population divided by ' + str(per) + ', summed over ' + str(len(deaths)) + ' countries with both values; ' + str(missing) + ' lacked one of them. The total is ' + str(round(total)) + ' deaths. Rates that are not per the stated base, or rates defined for a sub-population such as live births, give counts only by this approximation.'
    return {'facts': facts, 'summary': summary}

