def tool(data, params):
    legal = params['legal']
    supp = params['supportive']
    enf = params['enforcement']
    unit_l = data[legal]
    names = data['names']
    regions = data['regions']
    def span(code):
        out = {}
        for u, series in data[code].items():
            for y, v in series.items():
                if v is not None:
                    out.setdefault(u, {})[int(y)] = v
        return out
    S = {'L': span(legal), 'S': span(supp), 'E': span(enf)}
    units = [u for u in S['L'] if u in S['S'] or u in S['E']]
    facts = {}
    rows = []
    for u in units:
        l = S['L'][u]
        if len(l) == 0:
            continue
        y0 = min(l)
        y1 = max(l)
        row = {'unit': u, 'y0': y0, 'y1': y1, 'L0': l[y0], 'L1': l[y1], 'dL': l[y1] - l[y0]}
        for k in ('S', 'E'):
            s = S[k].get(u, {})
            if y1 in s:
                row[k + '1'] = s[y1]
                row['gap' + k] = l[y1] - s[y1]
            if y0 in s:
                row[k + '0'] = s[y0]
                row['gap' + k + '0'] = l[y0] - s[y0]
            if y0 in s and y1 in s:
                row['d' + k] = s[y1] - s[y0]
        rows.append(row)
    gaps = [r['gapS'] for r in rows if 'gapS' in r]
    gape = [r['gapE'] for r in rows if 'gapE' in r]
    dl = [r['dL'] for r in rows]
    facts['units_with_legal_score'] = len(rows)
    facts['units_with_supportive_gap'] = len(gaps)
    facts['units_with_enforcement_gap'] = len(gape)
    if dl:
        facts['median_legal_change'] = round(statistics.median(dl), 2)
    if gaps:
        facts['median_legal_minus_supportive'] = round(statistics.median(gaps), 2)
    if gape:
        facts['median_legal_minus_enforcement'] = round(statistics.median(gape), 2)
    wide = [r for r in rows if 'gapE' in r]
    wide.sort(key=lambda r: -r['gapE'])
    if wide:
        r = wide[0]
        facts['widest_enforcement_gap_unit'] = names.get(r['unit'], r['unit'])
        facts['widest_enforcement_gap_points'] = round(r['gapE'], 2)
        facts['widest_gap_year'] = r['y1']
    for r in rows:
        if r['unit'] in ('WLD',):
            for key in ('y0', 'y1', 'L0', 'L1', 'dL', 'gapS', 'gapE'):
                if key in r:
                    facts['WLD_' + key] = round(r[key], 2) if key not in ('y0', 'y1') else r[key]
    if rows:
        ys = [r['y0'] for r in rows] + [r['y1'] for r in rows]
        facts['earliest_year'] = min(ys)
        facts['latest_year'] = max(ys)
    summary = 'Legal scores are compared with supportive and enforcement scores for ' + str(len(rows)) + ' units between ' + str(facts.get('earliest_year')) + ' and ' + str(facts.get('latest_year')) + '. Missing years leave some gaps uncomputed, and the indices are read as reported.'
    if gape:
        summary += ' The median legal-minus-enforcement gap is ' + str(facts['median_legal_minus_enforcement']) + ' points at each unit\'s latest year.'
    return {'facts': facts, 'summary': summary}

