    def val(s, c, y):
        d = s.get(c)
        if d is None:
            return None
        v = d.get(y)
        if v is None:
            v = d.get(str(y))
        return v
    def compute(y):
        out = {}
        for c in regions:
            a = val(ra, c, y)
            b = val(rp, c, y)
            e = val(ua, c, y)
            f = val(up, c, y)
            if a is None or b is None or e is None or f is None:
                continue
            out[c] = (100 - a) / 100.0 * b + (100 - e) / 100.0 * f
        return out
    latest = None
    lres = {}
    for y in range(2030, base - 1, -1):
        r = compute(y)
        if len(r) >= minc:
            latest = y
            lres = r
            break
    facts = {}
    parts = []
    runs = [(base, compute(base))]
    if latest is not None and latest != base:
        runs.append((latest, lres))
    facts['latest_year'] = latest if latest is not None else 'none'
    for y, res in runs:
        total = sum(res.values())
        facts['countries_' + str(y)] = len(res)
        facts['lacking_' + str(y) + '_total'] = round(total)
        reg = {}
        for c in res:
            r = regions[c]
            reg[r] = reg.get(r, 0) + res[c]
        for r in sorted(reg):
            facts['lacking_' + str(y) + '_' + str(r)] = round(reg[r])
            facts['share_' + str(y) + '_' + str(r)] = round(100 * reg[r] / total, 1) if total > 0 else 0
        if res:
            top = max(res, key=lambda c: res[c])
            facts['top_country_' + str(y)] = names.get(top, top)
            facts['top_value_' + str(y)] = round(res[top])
