def tool(data, params):
    law = params['law']
    sfr = params['sfr']
    enf = params['enf']
    y0 = params['y0']
    y1 = params['y1']
    y2 = params['y2']
    regions = data['regions']
    codes = [law, sfr, enf]
    def ser(c):
        d = data[c]
        for u in d:
            return d[u]
        return {}
    S = {c: ser(c) for c in codes}
    def val(c, k, y):
        v = S[c].get(k, {})
        return v.get(y) if isinstance(v, dict) else None
    facts = {}
    def clean(c, y):
        out = {}
        for k in S[c]:
            if k in regions:
                v = S[c][k].get(y)
                if v is not None:
                    out[k] = v
        return out
    def quart(xs):
        s = sorted(xs)
        n = len(s)
        if n < 2:
            return None
        def q(p):
            pos = (n - 1) * p
            lo = int(math.floor(pos))
            hi = min(lo + 1, n - 1)
            return s[lo] + (s[hi] - s[lo]) * (pos - lo)
        return q(0.75) - q(0.25)
    for c in codes:
        for y in [y0, y1, y2]:
            d = clean(c, y)
            xs = list(d.values())
            p = c + '_' + str(y)
            facts[p + '_n'] = len(xs)
            if xs:
                facts[p + '_mean'] = round(statistics.mean(xs), 2)
                facts[p + '_min'] = min(xs)
                facts[p + '_max'] = max(xs)
                iq = quart(xs)
                if iq is not None:
                    facts[p + '_iqr'] = round(iq, 2)
            groups = {}
            for k in d:
                groups.setdefault(regions[k], []).append(d[k])
            for g in groups:
                facts[p + '_mean_' + g] = round(statistics.mean(groups[g]), 2)
    for a, b in [(y0, y2), (y1, y2)]:
        up = down = same = 0
        for k in S[law]:
            if k in regions:
                u = val(law, k, a)
                v = val(law, k, b)
                if u is not None and v is not None:
                    if v > u:
                        up += 1
                    elif v < u:
                        down += 1
