def tool(data, params):
    law = params['law']
    sfr = params['sfr']
    enf = params['enf']
    y0 = int(params['y0'])
    y1 = int(params['y1'])
    y2 = int(params['y2'])
    regs = data['regions']
    def ser(code):
        d = data[code]
        if not d:
            return {}
        u = sorted(d.keys())[0]
        return d[u]
    S = {'law': ser(law), 'sfr': ser(sfr), 'enf': ser(enf)}
    def vals(k, y):
        return {c: v[y] for c, v in S[k].items() if c in regs and y in v and v[y] is not None}
    def mean(x):
        return round(sum(x) / len(x), 2) if x else None
    def quart(x):
        if len(x) < 2:
            return None
        q = statistics.quantiles(x, n=4, method='inclusive')
        return round(q[2] - q[0], 2)
    facts = {}
    for k in S:
        for y in (y0, y1, y2):
            v = vals(k, y)
            xs = list(v.values())
            facts[k + '_n_' + str(y)] = len(xs)
            facts[k + '_mean_' + str(y)] = mean(xs)
            facts[k + '_min_' + str(y)] = min(xs) if xs else None
            facts[k + '_max_' + str(y)] = max(xs) if xs else None
            facts[k + '_iqr_' + str(y)] = quart(xs)
            g = {}
            for c, x in v.items():
                g.setdefault(regs[c], []).append(x)
            for r in sorted(g):
                facts[k + '_mean_' + r + '_' + str(y)] = mean(g[r])
    for a, b in ((y0, y2), (y1, y2)):
        va = vals('law', a)
        vb = vals('law', b)
        up = down = same = 0
        for c in va:
            if c in vb:
                if vb[c] > va[c]:
                    up += 1
                elif vb[c] < va[c]:
                    down += 1
                else:
                    same += 1
        t = str(a) + '_' + str(b)
        facts['law_rose_' + t] = up
        facts['law_fell_' + t] = down
        facts['law_same_' + t] = same
    L = vals('law', y2)
    for k in ('sfr', 'enf'):
        V = vals(k, y2)
        g = {}
        for c in L:
            if c in V:
                g.setdefault(regs[c], []).append(L[c] - V[c])
        for r in sorted(g):
            facts['gap_law_' + k + '_' + r + '_' + str(y2)] = mean(g[r])
    summary = 'Legal score compared with companion scores; world mean ' + str(facts['law_mean_' + str(y2)]) + ' in ' + str(y2) + ' across ' + str(facts['law_n_' + str(y2)]) + ' economies. Means are unweighted by country; groups follow the region mapping supplied.'
    return {'facts': facts, 'summary': summary}

