def tool(data, params):
    rural_acc = data[params['rural_access']]
    rural_pop = data[params['rural_pop']]
    urban_acc = data[params['urban_access']]
    urban_pop = data[params['urban_pop']]
    regions = data['regions']
    names = data['names']
    base = int(params.get('base_year', 2015))

    def val(series, c, y):
        d = series.get(c)
        if not d:
            return None
        return d.get(y)

    def years_of(*ss):
        ys = set()
        for s in ss:
            for c in s:
                if c in regions:
                    for y in s[c]:
                        ys.add(y)
        return ys

    def lacking(c, y):
        total = 0.0
        got = False
        for acc, pop in ((rural_acc, rural_pop), (urban_acc, urban_pop)):
            a = val(acc, c, y)
            p = val(pop, c, y)
            if a is None or p is None:
                return None
            total += (100.0 - a) / 100.0 * p
        return total

    def compute(y):
        res = {}
        for c in regions:
            v = lacking(c, y)
            if v is not None:
                res[c] = v
        return res

    common = years_of(rural_acc, urban_acc, rural_pop, urban_pop)
    latest = None
    for y in sorted(common, reverse=True):
        if len(compute(y)) >= 10:
            latest = y
            break
    facts = {}
    parts = []
    for label, y in (('base', base), ('latest', latest)):
        if y is None:
            facts[label + '_year'] = 'none'
            continue
        res = compute(y)
        world = sum(res.values())
        reg = {}
        for c, v in res.items():
            r = regions[c]
            reg[r] = reg.get(r, 0.0) + v
        facts[label + '_year'] = y
        facts[label + '_countries'] = len(res)
        facts[label + '_total_people'] = round(world)
        if res:
            top = sorted(res.items(), key=lambda kv: -kv[1])[0]
            facts[label + '_top_country'] = names.get(top[0], top[0])
            facts[label + '_top_country_people'] = round(top[1])
        for r in sorted(reg):
            share = reg[r] / world * 100.0 if world else 0.0
            facts[label + '_' + r + '_people'] = round(reg[r])
            facts[label + '_' + r + '_share_pct'] = round(share, 1)
        if reg:
            tr = sorted(reg.items(), key=lambda kv: -kv[1])[0][0]
            parts.append('In %s, %d people lacked electricity across %d countries with complete data; region %s held the largest share (%.1f%%).' % (y, round(world), len(res), tr, reg[tr] / world * 100.0 if world else 0.0))
    summary = ' '.join(parts) if parts else 'No country had complete data.'
    summary += ' Totals cover only countries with all four series present; others are excluded.'
    return {'facts': facts, 'summary': summary}

