def tool(data, params):
    rcode = params['rate_series']
    pcode = params['pop_series']
    year = str(params['year'])
    per = params.get('per', 100000)
    rate = data[rcode]
    pop = data[pcode]
    regions = data['regions']
    names = data['names']
    def val(d, u, y):
        s = d.get(u)
        if s is None:
            return None
        if y in s:
            return s[y]
        try:
            return s[int(y)]
        except Exception:
            return None
    totals = {}
    missing = 0
    used = 0
    total = 0.0
    for u in regions:
        r = val(rate, u, year)
        p = val(pop, u, year)
        if r is None or p is None:
            missing += 1
            continue
        c = r * p / per
        used += 1
        total += c
        g = regions[u]
        totals[g] = totals.get(g, 0.0) + c
    facts = {'year': year, 'countries_used': used, 'countries_missing': missing, 'global_count': round(total)}
    for g in sorted(totals):
        facts['count_' + str(g)] = round(totals[g])
    top = None
    for g in totals:
        if top is None or totals[g] > totals[top]:
            top = g
    if top is not None:
        facts['largest_region'] = str(names.get(top, top))
        facts['largest_share_pct'] = round(100 * totals[top] / total, 1) if total else 0
    summary = 'Deaths implied by ' + rcode + ' applied to ' + pcode + ' in ' + year + ' total ' + str(round(total)) + ' across ' + str(used) + ' countries; ' + str(missing) + ' countries lack a value for one series and are excluded, so the total is a lower bound. Counts equal rate times population divided by ' + str(per) + '.'
    return {'facts': facts, 'summary': summary}

