        if not d:
            return None
        v = d.get(y)
        if v is None:
            v = d.get(str(y))
        return v
    def calc(y):
        out = {}
        for c in regions:
            vals = [val(k, c, y) for k in (ra, rp, ua, up)]
            if any(v is None for v in vals):
                continue
            out[c] = (100 - vals[0]) / 100 * vals[1] + (100 - vals[2]) / 100 * vals[3]
        return out
    years = set()
    for c in regions:
        d = data[ra].get(c)
        if d:
            for y in d:
                years.add(int(y))
    base = int(params['base_year'])
    minc = int(params['min_countries'])
    latest = None
    for y in sorted(years, reverse=True):
        if len(calc(y)) >= minc:
            latest = y
            break
    facts = {}
    parts = []
    for label, y in (('base', base), ('latest', latest)):
        if y is None:
            facts['year_' + label] = 'no year with enough complete countries'
            continue
        res = calc(y)
        total = sum(res.values())
        tag = str(y)
        facts['year_' + label] = y
        facts['countries_' + tag] = len(res)
        facts['total_lacking_' + tag] = round(total)
        reg = {}
        for c, v in res.items():
            reg[regions[c]] = reg.get(regions[c], 0) + v
        for r in sorted(reg):
            facts['lacking_' + r + '_' + tag] = round(reg[r])
            facts['share_' + r + '_' + tag] = round(100 * reg[r] / total, 1) if total > 0 else 0
        ranked = sorted([(v, c) for c, v in res.items()], reverse=True)
        if ranked:
            facts['top_country_' + tag] = names.get(ranked[0][1], ranked[0][1])
        parts.append(tag + ': ' + str(round(total)) + ' people lacking electricity across ' + str(len(res)) + ' countries with complete data')
    summary = 'People without electricity access, computed as (100 minus access rate) per cent of rural and urban population, summed. ' + '; '.join(parts) + '. Countries missing any of the four series in a year are excluded, so totals cover only complete cases.'
    return {'facts': facts, 'summary': summary}

