    up = data[params['urban_pop']]
    base = int(params['base_year'])
    minc = int(params['min_countries'])
    regions = data['regions']
    names = data['names']
    def yr(d):
        return {int(y): v for y, v in d.items() if v is not None}
    comp = {}
    counts = {}
    for c in regions:
        if c in ra and c in rp and c in ua and c in up:
            a = yr(ra[c]); b = yr(rp[c]); d = yr(ua[c]); e = yr(up[c])
            out = {}
            for y in a:
                if y in b and y in d and y in e:
                    out[y] = (100 - a[y]) / 100.0 * b[y] + (100 - d[y]) / 100.0 * e[y]
                    counts[y] = counts.get(y, 0) + 1
            comp[c] = out
    ok = [y for y in counts if counts[y] >= minc]
    latest = max(ok) if ok else None
    facts = {}
    parts = []
    years = [base]
    if latest is not None and latest != base:
        years.append(latest)
    facts['latest_year'] = latest if latest is not None else 'no year with enough countries'
    for y in years:
        tot = 0.0
        n = 0
        reg = {}
        top = None
        for c in comp:
            if y in comp[c]:
                v = comp[c][y]
                tot += v
                n += 1
                r = regions[c]
                reg[r] = reg.get(r, 0.0) + v
                if top is None or v > top[1]:
                    top = (c, v)
        facts['total_' + str(y)] = round(tot)
        facts['countries_' + str(y)] = n
        if tot > 0:
            for r in sorted(reg):
                facts['region_' + str(r) + '_' + str(y)] = round(reg[r])
                facts['share_' + str(r) + '_' + str(y)] = round(100.0 * reg[r] / tot, 1)
            facts['top_country_' + str(y)] = names.get(top[0], top[0])
            facts['top_value_' + str(y)] = round(top[1])
            big = max(reg, key=lambda k: reg[k])
            parts.append(str(y) + ': ' + str(round(tot / 1e6, 1)) + ' million people lacked electricity across ' + str(n) + ' countries with complete data; the largest regional share was ' + str(big) + ' at ' + str(round(100.0 * reg[big] / tot, 1)) + ' per cent.')
        else:
            parts.append(str(y) + ': no country had complete data.')
    summary = 'People lacking electricity access, computed as (100 minus access rate) times population, rural and urban summed. ' + ' '.join(parts) + ' Coverage is limited to countries with all four series present in the year.'
    return {'facts': facts, 'summary': summary}

