def tool(data, params):
    rate_code = params['rate_code']
    pop_code = params['pop_code']
    year = str(params['year'])
    per = params.get('per', 100000)
    rates = data[rate_code]
    pops = data[pop_code]
    regions = data['regions']
    names = data['names']
    def pick(series, u, y):
        d = series.get(u)
        if d is None:
            return None
        if y in d:
            return d[y]
        if int(y) in d:
            return d[int(y)]
        return None
    units_r = list(rates.keys())
    units_p = list(pops.keys())
    if not units_r or not units_p:
        return {'facts': {'countries_counted': 0}, 'summary': 'No data available for the requested series.'}
    total = 0.0
    by_region = {}
    counted = 0
    missing = 0
    for c in regions:
        r = pick(rates, c, year) if c in rates else None
        p = pick(pops, c, year) if c in pops else None
        if r is None or p is None:
            missing += 1
            continue
        n = r * p / per
        total += n
        counted += 1
        reg = regions[c]
        by_region[reg] = by_region.get(reg, 0.0) + n
    facts = {'year': int(year), 'countries_counted': counted, 'countries_missing': missing, 'global_count_estimate': round(total)}
    top = None
    for reg in by_region:
        facts['count_' + str(reg)] = round(by_region[reg])
        if top is None or by_region[reg] > by_region[top]:
            top = reg
    if top is not None:
        facts['largest_region'] = str(names.get(top, top))
    summary = 'Converting ' + rate_code + ' (per ' + str(per) + ' people) with ' + pop_code + ' gives about ' + str(round(total)) + ' in ' + year + ', summed over ' + str(counted) + ' countries; ' + str(missing) + ' lacked a rate or population value and are excluded, so the total is a lower bound.'
    return {'facts': facts, 'summary': summary}

