    def span(d):
        ys = sorted(y for y, v in d.items() if v is not None)
        if not ys:
            return None
        return ys[0], d[ys[0]], ys[-1], d[ys[-1]]
    def collect(code):
        out = {}
        for u, d in data[code].items():
            out[u] = d
        return out
    def pick(code):
        s = data[code]
        res = {}
        for u, d in s.items():
            res[u] = d
        return res
    L = pick(legal)
    S = pick(supp)
    E = pick(enf)
    facts = {}
    rows = []
    for u in L:
        sl = span(L[u])
        if sl is None:
            continue
        ss = span(S.get(u, {})) if u in S else None
        se = span(E.get(u, {})) if u in E else None
        row = {'u': u, 'l': sl, 's': ss, 'e': se}
        rows.append(row)
    n = 0
    gs = []
    ge = []
    dl = []
    for r in rows:
        n += 1
        l = r['l']
        dl.append(l[3] - l[1])
        if r['s'] is not None and r['s'][2] == l[2]:
            gs.append(l[3] - r['s'][3])
        if r['e'] is not None and r['e'][2] == l[2]:
            ge.append(l[3] - r['e'][3])
    facts['economies_with_legal_index'] = n
    if dl:
        facts['mean_legal_change'] = round(statistics.mean(dl), 2)
        facts['median_legal_change'] = round(statistics.median(dl), 2)
    if gs:
        facts['n_supportive_gap'] = len(gs)
        facts['mean_legal_minus_supportive'] = round(statistics.mean(gs), 2)
    if ge:
        facts['n_enforcement_gap'] = len(ge)
        facts['mean_legal_minus_enforcement'] = round(statistics.mean(ge), 2)
    for r in rows:
        if r['u'] in ('WLD', 'world') or names.get(r['u'], '') == 'World':
            l = r['l']
            facts['world_legal_first'] = l[1]
            facts['world_legal_last'] = l[3]
            facts['world_first_year'] = l[0]
            facts['world_last_year'] = l[2]
