                facts['world_supportive_last'] = r['s'][3]
            if r['e'] is not None:
                facts['world_enforcement_last'] = r['e'][3]
    summary = 'Legal framework scores changed by a mean of ' + str(facts.get('mean_legal_change')) + ' points between first and last year across ' + str(n) + ' entries; where the other indices exist for the same last year, the mean legal score exceeds the supportive score by ' + str(facts.get('mean_legal_minus_supportive')) + ' and the enforcement score by ' + str(facts.get('mean_legal_minus_enforcement')) + ' points. Entries lacking a matching year are excluded from gaps.'
