def tool(data, params):
    ra = data[params['rural_access']]
    rp = data[params['rural_pop']]
    ua = data[params['urban_access']]
    up = data[params['urban_pop']]
    regions = data['regions']
    names = data['names']
    base = int(params['base_year'])
    minc = int(params['min_countries'])
    def val(s, c, y):
        d = s.get(c)
        if d is None:
            return None
        v = d.get(y)
        if v is None:
            v = d.get(str(y))
        return v
    def lacking(c, y):
        a = val(ra, c, y)
        b = val(rp, c, y)
        e = val(ua, c, y)
        f = val(up, c, y)
        if a is None or b is None or e is None or f is None:
            return None
        return (100 - a) * b / 100.0 + (100 - e) * f / 100.0
    years = set()
    for s in (ra, rp, ua, up):
        for c in s:
            for k in s[c]:
                years.add(int(k))
    latest = None
    for y in sorted(years):
        n = 0
        for c in regions:
            if lacking(c, y) is not None:
                n += 1
        if n >= minc:
            latest = y
    facts = {}
    parts = []
    if latest is None:
        return {'facts': {'latest_year': 'none'}, 'summary': 'No year has complete data for the minimum number of countries.'}
    facts['latest_year'] = latest
    for y in (base, latest):
        tot = {}
        per = {}
        for c in regions:
            v = lacking(c, y)
            if v is not None:
                per[c] = v
                r = regions[c]
                tot[r] = tot.get(r, 0) + v
        world = sum(tot.values())
        tag = str(y)
        facts['countries_' + tag] = len(per)
        facts['total_people_' + tag] = round(world)
        if per:
            top = max(per, key=lambda c: per[c])
            facts['largest_country_' + tag] = names.get(top, top)
            facts['largest_country_people_' + tag] = round(per[top])
        for r in sorted(tot):
            facts['people_' + r + '_' + tag] = round(tot[r])
            facts['share_pct_' + r + '_' + tag] = round(100.0 * tot[r] / world, 1) if world > 0 else 0
        if tot:
            tr = max(tot, key=lambda r: tot[r])
            parts.append('In ' + tag + ', ' + str(round(world / 1e6, 1)) + ' million people in ' + str(len(per)) + ' countries lacked electricity access; region ' + tr + ' held ' + str(round(100.0 * tot[tr] / world, 1)) + ' per cent.')
        else:
            parts.append('In ' + tag + ', no country has complete data.')
    parts.append('Totals cover only countries with all four series present in the year; others are omitted.')
    return {'facts': facts, 'summary': ' '.join(parts)}

