            if isinstance(row, dict):
                v = row.get(year, row.get(str(year)))
                if v is not None and c in regions:
                    res[c] = v
        return res
    def quart(xs):
        s = sorted(xs)
        n = len(s)
        if n < 2:
            return 0
        q = statistics.quantiles(s, n=4, method='inclusive')
        return q[2] - q[0]
