        s = series[u]
        if y in s:
            return s[y]
        if str(y) in s:
            return s[str(y)]
        return None
    def latest(u):
        best = None
        for y in series[u]:
            if best is None or int(y) > best:
                best = int(y)
        return best
    def earliest_after(u, y0):
        best = None
        for y in series[u]:
            if int(y) >= y0 and (best is None or int(y) < best):
                best = int(y)
        return best
    facts['latest_year_in_data'] = latest_year
    wld = 'WLD'
    if wld in series:
        ly = latest(wld)
        facts['world_level'] = round(val(wld, ly), 2)
        facts['world_level_year'] = ly
        for tag, b in (('2015', base1), ('2020', base2)):
            by = earliest_after(wld, b)
            if by is not None and by < ly:
                facts['world_change_since_' + tag] = round(val(wld, ly) - val(wld, by), 2)
                facts['world_base_year_used_' + tag] = by
