def tool(data, params):
    code = params['series']
    y1 = int(params['base_year_a'])
    y2 = int(params['base_year_b'])
    s = data[code]
    regions = data['regions']
    names = data['names']
    facts = {}
    # per-economy: latest value and year
    latest = {}
    for u in s:
        for c, ys in s[u].items():
            if c not in regions:
                continue
            yrs = [int(y) for y in ys if ys[y] is not None]
            if yrs:
                m = max(yrs)
                v = ys[m] if m in ys else ys[str(m)]
                latest[c] = (m, v, ys)
    def get(ys, y):
        if y in ys and ys[y] is not None:
            return ys[y]
        if str(y) in ys and ys[str(y)] is not None:
            return ys[str(y)]
        return None
    def earliest_from(ys, y):
        cand = [int(k) for k in ys if int(k) >= y and ys[k] is not None]
        if not cand:
            return None
        m = min(cand)
        return (m, get(ys, m))
    ly = max([t[0] for t in latest.values()]) if latest else None
    if ly is None:
        return {'facts': {'economies': 0}, 'summary': 'No data are available for ' + code + '.'}
    cur = {c: get(t[2], ly) for c, t in latest.items()}
    cur = {c: v for c, v in cur.items() if v is not None}
    facts['latest_year'] = ly
    facts['economies_latest'] = len(cur)
    facts['world_mean_latest'] = round(statistics.mean(cur.values()), 2) if cur else 0
    groups = {}
    for c, v in cur.items():
        groups.setdefault(regions[c], []).append(v)
    for g in sorted(groups):
        facts['mean_' + g] = round(statistics.mean(groups[g]), 2)
    summary_bits = []
    for tag, by in (('a', y1), ('b', y2)):
        up = down = same = 0
        diffs = []
        used = set()
        for c, v in cur.items():
            e = earliest_from(latest[c][2], by)
            if e is None or e[0] >= ly:
                continue
            used.add(e[0])
            d = v - e[1]
            diffs.append(d)
            if d > 0:
                up += 1
            elif d < 0:
                down += 1
            else:
                same += 1
        facts['rising_since_' + str(by)] = up
        facts['falling_since_' + str(by)] = down
        facts['unchanged_since_' + str(by)] = same
        if diffs:
            facts['mean_change_since_' + str(by)] = round(statistics.mean(diffs), 2)
            facts['comparison_year_' + str(by)] = min(used)
        summary_bits.append('Since ' + str(by) + ' (earliest comparable year ' + str(min(used) if used else 'n/a') + '), ' + str(up) + ' economies rose, ' + str(down) + ' fell and ' + str(same) + ' were unchanged.')
    summary = 'Legal framework index ' + code + ' stands at a mean of ' + str(facts['world_mean_latest']) + ' across ' + str(len(cur)) + ' economies in ' + str(ly) + '. ' + ' '.join(summary_bits) + ' Coverage is uneven and the index is reported only for some years.'
    return {'facts': facts, 'summary': summary}

def tool(data, params):
    code = params['series']
    base1 = params.get('base1', 2015)
    base2 = params.get('base2', 2020)
