        if str(y) in d:
            return d[str(y)]
        return None
    def yrs(d):
        out = []
        for k in d:
            try:
                out.append(int(k))
            except Exception:
                pass
        return out
    latest_year = None
    for u in s:
        if u in regions:
            ys = yrs(s[u])
            if ys:
                m = max(ys)
                if latest_year is None or m > latest_year:
                    latest_year = m
    facts = {}
    if latest_year is None:
        return {'facts': {'latest_year': 'no data'}, 'summary': 'No country data are available for the series.'}
    facts['latest_year'] = latest_year
    def latest_of(d):
        ys = yrs(d)
        if not ys:
            return None, None
        y = max(ys)
        return y, val(d, y)
    def run(base, tag):
        rise = fall = same = 0
        diffs = []
        for u in s:
