        facts['rising_since_' + tag] = rise
        facts['falling_since_' + tag] = fall
        facts['unchanged_since_' + tag] = same
        if diffs:
            facts['mean_change_since_' + tag] = round(statistics.mean(diffs), 2)
        else:
            facts['mean_change_since_' + tag] = 'no data'
    import statistics
    run(base1, str(base1))
    run(base2, str(base2))
    lv = [val(s[u], latest_year) for u in s if u in regions and val(s[u], latest_year) is not None]
    facts['economies_latest'] = len(lv)
