    summary = ('Across ' + str(len(lv)) + ' economies the mean of ' + code + ' in ' + str(latest_year) + ' is ' + str(facts['mean_level_latest']) + ' (index score). Since ' + str(base1) + ' ' + str(facts['rising_since_' + str(base1)]) + ' economies rose, ' + str(facts['falling_since_' + str(base1)]) + ' fell and ' + str(facts['unchanged_since_' + str(base1)]) + ' were unchanged; since ' + str(base2) + ' ' + str(facts['rising_since_' + str(base2)]) + ' rose, ' + str(facts['falling_since_' + str(base2)]) + ' fell and ' + str(facts['unchanged_since_' + str(base2)]) + ' were unchanged. Where a base year is missing, the earliest later year with data is used. Group means are unweighted.')
