required-pace-comparison.code:
def tool(data, params):
    code = params['series']
    unit = params['unit']
    target = params['target']
    target_year = params.get('target_year', 2030)
    base_year = params.get('base_year', 2015)
    s = data[code][unit]
    ys = sorted(s.keys(), key=lambda y: int(y))
    ys = [y for y in ys if s[y] is not None]
    if not ys:
        return {'facts': {'status': 'no data'}, 'summary': 'No observations are available for ' + code + '.'}
    ly = ys[-1]
    lv = s[ly]
    base = [y for y in ys if int(y) <= int(base_year)]
    if not base:
        return {'facts': {'latest_year': int(ly), 'latest_value': lv, 'status': 'no base year data'}, 'summary': 'No observation exists in or before ' + str(base_year) + ' for ' + code + ', so the observed pace cannot be computed. The latest value is ' + str(round(lv, 2)) + ' in ' + str(ly) + '.'}
    by = base[-1]
    bv = s[by]
    left = int(target_year) - int(ly)
    elapsed = int(ly) - int(by)
    if left <= 0 or elapsed <= 0:
        return {'facts': {'latest_year': int(ly), 'latest_value': lv, 'status': 'no interval'}, 'summary': 'The latest year ' + str(ly) + ' leaves no interval to compute a pace.'}
    required = (target - lv) / left
    observed = (lv - bv) / elapsed
    facts = {'latest_year': int(ly), 'latest_value': round(lv, 3), 'base_year_used': int(by), 'base_value': round(bv, 3), 'target': target, 'required_change_per_year': round(required, 4), 'observed_change_per_year': round(observed, 4)}
    if observed != 0:
        ratio = required / observed
        facts['ratio_required_to_observed'] = round(ratio, 3)
        rtxt = 'The required pace is ' + str(round(ratio, 2)) + ' times the observed pace' + (' and in the opposite direction to it.' if ratio < 0 else '.')
    else:
        rtxt = 'The observed change is zero, so no ratio can be formed.'
    summary = code + ' stood at ' + str(round(lv, 2)) + ' (' + unit + ') in ' + str(ly) + '. Reaching ' + str(target) + ' by ' + str(target_year) + ' needs a change of ' + str(round(required, 3)) + ' per year; the observed change from ' + str(by) + ' was ' + str(round(observed, 3)) + ' per year. ' + rtxt + ' The target value is as supplied and may be read in more than one way.'
    return {'facts': facts, 'summary': summary}
